import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;class PublicExamplesTest{static String capture(Runnable action){PrintStream previous=System.out;ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(PrintStream out=new PrintStream(bytes,true,StandardCharsets.UTF_8)){System.setOut(out);action.run();}finally{System.setOut(previous);}return bytes.toString(StandardCharsets.UTF_8).replace("\r\n","\n");}@Test void publishedCapacityTwo(){Object q=TaskBinding.create(2);assertEquals("",capture(()->{TaskBinding.push(q,'A');TaskBinding.push(q,'B');}));assertEquals("Стек переполнен\n",capture(()->TaskBinding.push(q,'C')));assertEquals("",capture(()->{assertEquals('B',TaskBinding.pop(q));assertEquals('A',TaskBinding.pop(q));}));assertEquals("Стек пуст\n",capture(()->assertEquals('\0',TaskBinding.pop(q))));}}
